/**
 * Review Coordinator
 *
 * Dormant coordinator that reviews files generated by implementation coordinators.
 * Maintains FIFO queue for review requests.
 * Spawns SwarmCoordinator with reviewer agents to perform reviews.
 * Injects errors (50% rate) and sends responses back to requesting coordinators.
 *
 * Flow:
 * 1. Receive review request → add to FIFO queue
 * 2. Process queue: spawn SwarmCoordinator with reviewers
 * 3. Inject errors (50% of files)
 * 4. Send review response to requesting coordinator
 * 5. Track review metrics
 */

import { DormantCoordinatorBase } from '../lib/dormant-coordinator-base.js';
import { SwarmCoordinator } from '../../../.claude-flow-novice/dist/src/coordination/swarm-coordinator.js';
import { ConfigManager } from '../../../.claude-flow-novice/dist/src/config/config-manager.js';
import { Logger } from '../../../.claude-flow-novice/dist/src/core/logger.js';
import * as fs from 'fs/promises';

export class ReviewCoordinator extends DormantCoordinatorBase {
  constructor(id, redisUrl, errorInjectionRate = 0.5) {
    super(id, redisUrl);

    this.errorInjectionRate = errorInjectionRate; // 50% by default
    this.reviewQueue = [];
    this.swarmCoordinator = null;
    this.reviewsCompleted = 0;
    this.errorsInjected = 0;

    // Override message handlers
    this.setupReviewHandlers();
  }

  /**
   * Setup review-specific message handlers
   */
  setupReviewHandlers() {
    this.messageHandlers.set('review', this.handleReviewRequest.bind(this));
  }

  /**
   * Initialize swarm coordinator for reviews
   */
  async initializeSwarm() {
    console.log(`[${this.id}] Initializing SwarmCoordinator for reviews...`);

    // Load environment
    const apiKey = process.env.Z_AI_API_KEY;
    if (!apiKey) {
      throw new Error('Z_AI_API_KEY not found in environment');
    }

    // Initialize ConfigManager
    const configManager = ConfigManager.getInstance();
    await configManager.init();

    // Create logger
    const logger = new Logger(
      { level: 'info', format: 'text', destination: 'console' },
      { component: this.id }
    );

    // Create provider config
    const providerConfig = {
      providers: {
        zai: {
          apiKey,
          model: 'glm-4.6',
          maxTokens: 8192,
          temperature: 0.7,
          enableCaching: false,
        },
      },
      defaultProvider: 'zai',
      tieredRouting: {
        enabled: false,
      },
      monitoring: {
        enabled: false,
      },
    };

    // Create SwarmCoordinator
    this.swarmCoordinator = new SwarmCoordinator(
      {
        id: `${this.id}-swarm`,
        objective: 'Review generated files',
        topology: 'mesh',
        providerConfig,
        configManager,
        redisUrl: this.redisUrl,
        enableMonitoring: false,
        enableSQLiteMemory: false,
      },
      logger
    );

    await this.swarmCoordinator.start();

    // Register reviewer agents
    for (let i = 1; i <= 3; i++) {
      await this.swarmCoordinator.registerAgent(
        `${this.id}-reviewer-${i}`,
        'reviewer',
        ['file-review', 'validation']
      );
    }

    console.log(`[${this.id}] SwarmCoordinator initialized with 3 reviewers`);
  }

  /**
   * Handle review request
   */
  async handleReviewRequest(message) {
    console.log(`[${this.id}] Review request from ${message.from}: ${message.data.fileCount} files`);

    this.reviewQueue.push({
      id: message.id,
      type: 'review',
      correlationId: message.correlationId,
      from: message.from,
      data: message.data,
      receivedAt: Date.now()
    });

    console.log(`[${this.id}] Review queue size: ${this.reviewQueue.length}`);
  }

  /**
   * Process review request
   */
  async processRequest(request) {
    if (request.type !== 'review') {
      console.log(`[${this.id}] Skipping non-review request: ${request.type}`);
      return;
    }

    console.log(`[${this.id}] Processing review request from ${request.from}`);

    try {
      // Initialize swarm if needed
      if (!this.swarmCoordinator) {
        await this.initializeSwarm();
      }

      // Review files
      const files = request.data.files;
      const reviewResults = await this.reviewFiles(files);

      // Count errors
      const errorFiles = reviewResults.filter(r => r.hasError);
      const hasErrors = errorFiles.length > 0;

      console.log(`[${this.id}] Review complete: ${errorFiles.length}/${files.length} files with errors`);

      // Send response back to requesting coordinator
      await this.sendResponse(request.from, request.correlationId, {
        hasErrors,
        errorFiles,
        successFiles: reviewResults.filter(r => !r.hasError),
        totalReviewed: files.length,
        errorRate: errorFiles.length / files.length
      });

      // Update stats
      this.reviewsCompleted++;
      this.stats.requestsCompleted++;
      this.completedRequests.add(request.id);

      console.log(`[${this.id}] Review response sent to ${request.from}`);
    } catch (error) {
      console.error(`[${this.id}] Error processing review:`, error);

      // Send error response
      await this.sendResponse(request.from, request.correlationId, {
        hasErrors: true,
        error: error.message
      }, false);
    }
  }

  /**
   * Review files and inject errors
   */
  async reviewFiles(files) {
    console.log(`[${this.id}] Reviewing ${files.length} files...`);

    const reviewResults = [];

    for (const file of files) {
      // Inject error based on error injection rate
      const hasError = Math.random() < this.errorInjectionRate;

      if (hasError) {
        this.errorsInjected++;
      }

      const result = {
        fileName: file.fileName,
        filePath: file.filePath,
        fileNumber: file.fileNumber,
        hasError,
        error: hasError ? 'Simulated error: File content validation failed' : null,
        reviewedAt: Date.now(),
        reviewerId: `${this.id}-reviewer-${Math.floor(Math.random() * 3) + 1}`
      };

      reviewResults.push(result);

      // Simulate review time
      await this.sleep(50 + Math.random() * 100); // 50-150ms per file
    }

    // Store review metrics in Redis
    await this.mainClient.hSet(`coordinator:${this.id}:metrics`, {
      reviewsCompleted: this.reviewsCompleted.toString(),
      errorsInjected: this.errorsInjected.toString(),
      errorInjectionRate: this.errorInjectionRate.toString()
    });

    console.log(`[${this.id}] Review complete: ${this.errorsInjected} total errors injected`);

    return reviewResults;
  }

  /**
   * Override run loop to process FIFO queue
   */
  async run() {
    console.log(`[${this.id}] Starting review coordinator run loop`);
    this.running = true;

    while (this.running) {
      // Process review queue when in dormant state
      if (this.state === 'dormant' && this.reviewQueue.length > 0) {
        const request = this.reviewQueue.shift();

        this.transitionState('active');

        try {
          await this.processRequest(request);
        } catch (error) {
          console.error(`[${this.id}] Error processing review:`, error);
        }

        this.transitionState('dormant');
      }

      await this.sleep(100);
    }

    console.log(`[${this.id}] Run loop ended`);
  }

  /**
   * Get review statistics
   */
  getReviewStats() {
    return {
      ...this.getStats(),
      reviewsCompleted: this.reviewsCompleted,
      errorsInjected: this.errorsInjected,
      errorInjectionRate: this.errorInjectionRate,
      queueSize: this.reviewQueue.length
    };
  }

  /**
   * Cleanup
   */
  async shutdown() {
    console.log(`[${this.id}] Shutting down review coordinator...`);

    if (this.swarmCoordinator) {
      await this.swarmCoordinator.stop();
    }

    await super.shutdown();
  }
}
